*{box-sizing:border-box}
html{scroll-behavior:smooth}
body{margin:0;font-family:system-ui,-apple-system,"Segoe UI","Noto Sans TC",sans-serif;color:#0f172a;background:#fff;line-height:1.6;overflow-x:hidden}
h1,h2,h3,p{margin:0}
a{color:#1d4ed8}
:focus-visible{outline:3px solid #f59e0b;outline-offset:2px}
.sr-only{position:absolute;width:1px;height:1px;overflow:hidden;clip:rect(0 0 0 0);white-space:nowrap}
.skip{position:absolute;left:-999px;top:0;background:#fff;padding:8px;z-index:10}
.skip:focus{left:0}
.topbar{padding:16px 24px;border-bottom:1px solid #e2e8f0}
.logo{font-weight:700;font-size:1.25rem;color:#1e3a8a}
.hero{text-align:center;padding:72px 24px;background:#eff6ff}
.hero h1{font-size:clamp(2.2rem,6vw,3.5rem);color:#1e3a8a}
.lead{max-width:36rem;margin:16px auto 28px;font-size:1.2rem;color:#334155}
.actions{display:flex;gap:12px;justify-content:center;flex-wrap:wrap}
.btn{display:inline-block;padding:12px 24px;border-radius:8px;font:inherit;font-weight:600;text-decoration:none;cursor:pointer;border:2px solid #1d4ed8;text-align:center}
.btn.primary{background:#1d4ed8;color:#fff}
.btn.outline{background:#fff;color:#1d4ed8}
.section{max-width:1100px;margin:0 auto;padding:56px 24px}
.section>h2{font-size:1.75rem;text-align:center;margin-bottom:28px}
.features{list-style:none;margin:0;padding:0;display:grid;grid-template-columns:repeat(auto-fit,minmax(220px,1fr));gap:20px}
.features li{padding:20px;border:1px solid #e2e8f0;border-radius:12px}
.features h3{margin-bottom:8px;color:#1e3a8a}
.muted{color:#475569}
.notice{max-width:36rem;margin:0 auto;padding:32px 24px;text-align:center;border:1px dashed #64748b;border-radius:12px;display:flex;flex-direction:column;gap:12px;align-items:center}
.notice.error{border:2px solid #b91c1c;background:#fef2f2}
.notice.error h3{color:#991b1b}
.spinner{display:inline-block;width:1em;height:1em;border:3px solid #cbd5e1;border-top-color:#1d4ed8;border-radius:50%;animation:spin 1s linear infinite;vertical-align:-2px}
@keyframes spin{to{transform:rotate(360deg)}}
.toggle{display:flex;width:fit-content;max-width:100%;margin:0 auto 28px;border:2px solid #1d4ed8;border-radius:999px;overflow:hidden}
.toggle button{font:inherit;font-weight:600;padding:8px 20px;border:0;background:#fff;color:#1d4ed8;cursor:pointer}
.toggle button[aria-pressed=true]{background:#1d4ed8;color:#fff}
.save{font-size:.85em}
.plans{list-style:none;margin:0;padding:0;display:grid;grid-template-columns:repeat(auto-fit,minmax(240px,1fr));gap:20px}
.plan{position:relative;display:flex;flex-direction:column;gap:12px;padding:24px;border:1px solid #cbd5e1;border-radius:12px}
.plan.rec{border:2px solid #1d4ed8;box-shadow:0 4px 16px rgba(29,78,216,.15)}
.badge{position:absolute;top:-14px;left:24px;background:#1d4ed8;color:#fff;padding:2px 12px;border-radius:999px;font-size:.85rem;font-weight:600}
.price strong{font-size:1.75rem}
.price span{color:#475569}
.checks{list-style:none;margin:0 0 8px;padding:0;flex:1}
.checks li{padding:4px 0 4px 1.5em;position:relative}
.checks li::before{content:"✓";position:absolute;left:0;color:#15803d;font-weight:700}
.table-title{margin:48px 0 16px;text-align:center;font-size:1.4rem}
.compare{width:100%;border-collapse:collapse;table-layout:fixed}
.compare th,.compare td{border:1px solid #cbd5e1;padding:10px 8px;text-align:center;overflow-wrap:anywhere}
.compare thead th{background:#eff6ff}
.compare tbody th{text-align:left;background:#f8fafc}
.faq{max-width:760px;margin:0 auto}
.faq details{border-bottom:1px solid #e2e8f0;padding:4px 0}
.faq summary{cursor:pointer;font-weight:600;padding:12px 0}
.faq details p{padding:0 0 16px;color:#334155}
.footer{background:#0f172a;color:#e2e8f0;padding:40px 24px;text-align:center;display:flex;flex-direction:column;gap:10px}
.footer a{color:#93c5fd}
@media (max-width:600px){
  .compare{font-size:.8rem}
  .compare th,.compare td{padding:8px 4px}
  .hero{padding:48px 20px}
  .section{padding:40px 16px}
}

